{
  "packet_id": "H6-T01-1",
  "claim_id": "C027",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C027.component",
    "value": "If bookings are too sparse to apply the persistence rule, the bottleneck should not be claimed as established.",
    "scope": "An evidential restriction conditional on inability to apply the rule.",
    "provenance": {
      "refs": [
        {
          "source_id": "P011",
          "role": "CONTEXT"
        },
        {
          "source_id": "P014",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P014 explicitly supplies the sparsity condition and restriction on claiming an established bottleneck; P011 identifies the referenced rule."
    }
  },
  "signal_basis": {
    "component_id": "C027.signal_basis",
    "value": "The booking sequence is too sparse to evaluate the persistence rule requiring recurrence on multiple booking days in each investigation week and the same stage having the greatest documented delay burden in both weeks.",
    "scope": "Application of the provisional rule during the two-week investigation; the rule supports practical selection rather than statistical proof or causal identification.",
    "provenance": {
      "refs": [
        {
          "source_id": "P011",
          "role": "SUPPORT"
        },
        {
          "source_id": "P014",
          "role": "SUPPORT"
        },
        {
          "source_id": "P025",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the rule, the inability to apply it because of sparse bookings, and its inferential limits."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C027.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The restriction is warranted without establishing an additional empirical relation."
    }
  },
  "rationale": "When sparse observations prevent application of the stipulated persistence rule, that procedure cannot establish a persistent bottleneck. Withholding that conclusion is licensed within the claim's explicit bounds.",
  "uncertainty": "A bottleneck may nevertheless exist; the claim concerns insufficient evidence to establish it through this procedure.",
  "anomalies": []
}
